import{_ as r,o as t,c as s,a5 as o}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-18-view-workspace-members/report3_spec.md","filePath":"feature/agency-workspace/3-4-18-view-workspace-members/report3_spec.md"}'),i={name:"feature/agency-workspace/3-4-18-view-workspace-members/report3_spec.md"};function a(l,e,n,c,m,p){return t(),s("div",null,[...e[0]||(e[0]=[o("<p><strong>3.4.18 View Workspace Members</strong></p><p><strong>Function Trigger</strong></p><p>Begins when a Workspace member opens the members screen of a Workspace.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Workspace members with role MANAGER, CREATOR, or CLIENT.</li><li><strong>Purpose</strong>: Shows who takes part in the Workspace and the role each member holds.</li><li><strong>Interface</strong>: Workspace members screen, listing members with their roles.</li><li><strong>Data Processing</strong>: The system loads the Workspace, confirms the caller is an active member of that same Workspace, then lists every member of the Workspace together with the display name and email of each member&#39;s user or client profile.</li></ul><p><strong>Screen Layout</strong></p><p>Figure - Workspace Members Screen:</p><ul><li>A table of members with name, email, role, and the date each member joined.</li><li>Role badges for MANAGER, CREATOR, and CLIENT.</li><li>Active members only; members who have left or were removed do not appear.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: the Workspace identifier; the caller&#39;s authenticated identity.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: the Workspace record; the caller&#39;s active membership row; the Workspace&#39;s active membership rows; the user records and client profiles those memberships reference.</li><li><strong>Output</strong>: the list of members - id, workspaceId, userId, fullName, email, clientProfileId, role, joinedAt, isActive. Role is one of MANAGER, CREATOR, CLIENT - there is no OWNER at Workspace level.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-29</strong>: The Workspace must exist; otherwise 404 WORKSPACE_NOT_FOUND. A caller with no active membership in that Workspace cannot read it regardless of system role (except ADMIN).</li><li><strong>BR-30</strong>: The caller must be an active member of the very Workspace being viewed; otherwise 403 WORKSPACE_ACCESS_DENIED. This is the same re-check that cuts off access once a member is removed or leaves.</li><li><strong>BR-31</strong>: The role list at Workspace level is MANAGER, CREATOR, CLIENT; OWNER is not a Workspace role.</li><li><strong>BR-35</strong>: Role/permission checks re-read the caller&#39;s role from the DB at request time; SystemRole.ADMIN bypasses the membership check.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>The Workspace must exist; otherwise 404 WORKSPACE_NOT_FOUND, toast <strong>MSG38</strong>.</li><li>The caller must hold an active membership in that Workspace; otherwise 403 WORKSPACE_ACCESS_DENIED, toast <strong>MSG40</strong>.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>Member opens the Workspace members screen.</li><li>System loads the Workspace; if it does not exist the request fails with 404 WORKSPACE_NOT_FOUND.</li><li>System confirms the caller holds an active membership in that Workspace; otherwise the request fails with 403 WORKSPACE_ACCESS_DENIED.</li><li>System reads the Workspace&#39;s active membership rows and resolves the display name and email of each member from the referenced user record or client profile.</li><li>Screen renders the member table with each member&#39;s role and join date.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: Workspace does not exist -&gt; 404 WORKSPACE_NOT_FOUND, toast <strong>MSG38</strong>. 2.a2: The member returns to the Workspace list.</li><li>3.a1: Caller is not an active member of that Workspace -&gt; 403 WORKSPACE_ACCESS_DENIED, toast <strong>MSG40</strong>. 3.a2: The member returns to the Workspace list; the Workspace they tried to view does not appear.</li><li>4.a1: A member has no linked user account but is attached through a client profile -&gt; the client profile&#39;s display name is shown and the email is empty. 4.a2: The row renders normally with the remaining columns unaffected.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>No data is changed; the Workspace members are displayed.</li></ul>",14)])])}const d=r(i,[["render",a]]);export{g as __pageData,d as default};
